//! `SystemOwnership::inspect` on Unix against the table that the .NET code produced on Linux
//! (`rust/tests/golden/ownership-unix.json`, regenerated by `rust/tools/ownership-oracle`).
#![cfg(unix)]

use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};

use serde_json::{Value, json};
use sermofur_core::ownership::{FileOwnership, SystemOwnership};
use uuid::Uuid;

/// A fresh folder, removed on drop.
struct TempRoot(PathBuf);

impl Drop for TempRoot {
    fn drop(&mut self) {
        // The folder of mode 000 must be searchable again, or it cannot be removed.
        let _ = fs::set_permissions(self.0.join("locked"), fs::Permissions::from_mode(0o700));
        let _ = fs::remove_dir_all(&self.0);
    }
}

#[test]
fn inspect_matches_the_oracle() {
    let text = fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/ownership-unix.json"
    ))
    .expect("the golden file exists");
    let golden: Value = serde_json::from_str(&text).expect("valid JSON");
    assert_eq!(golden["os"], "unix");
    let root = TempRoot(std::env::temp_dir().join(format!("sermofur-owner-{}", Uuid::new_v4())));
    let under = |relative: &str| root.0.join(relative);
    fs::create_dir_all(under("dir")).expect("dir");
    fs::write(under("file.txt"), "x").expect("file");
    std::os::unix::fs::symlink(under("file.txt"), under("link-file")).expect("link");
    std::os::unix::fs::symlink(under("dir"), under("link-dir")).expect("link");
    std::os::unix::fs::symlink(under("nowhere"), under("link-dangling")).expect("link");
    let fifo = std::process::Command::new("mkfifo")
        .arg(under("fifo"))
        .status()
        .expect("mkfifo runs");
    assert!(fifo.success(), "mkfifo failed");
    // A folder that cannot be searched: its children cannot be read (EACCES), unless as root.
    fs::create_dir(under("locked")).expect("locked");
    fs::set_permissions(under("locked"), fs::Permissions::from_mode(0o000)).expect("mode 000");
    let base = root.0.to_str().expect("UTF-8 path").to_owned();
    let path_of = |name: &str| -> String {
        let under = |relative: &str| format!("{base}/{relative}");
        match name {
            "dir" => under("dir"),
            "dir_trailing_separator" => under("dir/"),
            "file" => under("file.txt"),
            "file_trailing_separator" => under("file.txt/"),
            "absent" => under("absent"),
            "absent_parent" => under("absent/child"),
            "through_file" => under("file.txt/child"),
            "link_to_file" => under("link-file"),
            "link_to_dir" => under("link-dir"),
            "link_dangling" => under("link-dangling"),
            "fifo" => under("fifo"),
            "no_search_parent" => under("locked/child"),
            "system_dir" => "/".to_owned(),
            "system_file" => "/etc/passwd".to_owned(),
            other => panic!("unknown case {other}"),
        }
    };
    // The oracle ran as an ordinary user, for whom `/` and `/etc/passwd` belong to another
    // account and a folder of mode 000 cannot be searched; none of this holds for root.
    let root_user = runs_as_root();
    let mut mismatches = Vec::new();
    let cases = golden["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 14);
    for case in cases {
        let name = case["name"].as_str().expect("a name");
        if root_user && (name.starts_with("system_") || name == "no_search_parent") {
            continue;
        }
        let actual = match SystemOwnership.inspect(Path::new(&path_of(name))) {
            Ok(None) => json!({ "name": name, "status": null }),
            Ok(Some(s)) => json!({ "name": name, "status": {
                "isRegularFile": s.is_regular_file,
                "isDirectory": s.is_directory,
                "isOwnedByCurrentUser": s.is_owned_by_current_user,
            }}),
            Err(_) => json!({ "name": name, "error": true }),
        };
        if &actual != case {
            mismatches.push(format!("{name}: expected {case}, got {actual}"));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

/// Whether the tests run as root, read from the owner of a fresh file (no extra dependency).
fn runs_as_root() -> bool {
    use std::os::unix::fs::MetadataExt;
    let probe = std::env::temp_dir().join(format!("sermofur-uid-{}", Uuid::new_v4()));
    fs::write(&probe, "").expect("probe");
    let uid = fs::metadata(&probe).expect("probe").uid();
    let _ = fs::remove_file(&probe);
    uid == 0
}

/// Runs `sudo -n` with the arguments; true on success.
fn sudo(args: &[&str]) -> bool {
    std::process::Command::new("sudo")
        .arg("-n")
        .args(args)
        .status()
        .is_ok_and(|status| status.success())
}

/// Port of `HardeningTests.RealEntryOfAnotherAccountIsRefused` at the level of `inspect`: root
/// through passwordless sudo, as on the CI runners. Only the group changes, then the owner, so
/// that an owner read from the group would fail the test. It fails when sudo is missing, as the
/// .NET test does; `SERMOFUR_ALLOW_SUDO_SKIP=1` turns that failure into a skip on a machine
/// without passwordless sudo.
#[test]
fn real_entry_of_another_account_is_refused() {
    if !sudo(&["true"]) {
        assert!(
            std::env::var("SERMOFUR_ALLOW_SUDO_SKIP").is_ok_and(|v| v == "1"),
            "This test needs passwordless sudo to create an entry owned by root (SERMOFUR_ALLOW_SUDO_SKIP=1 skips it)."
        );
        eprintln!("no passwordless sudo: test skipped");
        return;
    }
    let root = TempRoot(std::env::temp_dir().join(format!("sermofur-owner-{}", Uuid::new_v4())));
    let entry = root.0.join("entry");
    fs::create_dir_all(&entry).expect("entry");
    let path = entry.to_str().expect("UTF-8 path");
    let owned = || {
        SystemOwnership
            .inspect(&entry)
            .expect("readable")
            .expect("present")
            .is_owned_by_current_user
    };
    assert!(sudo(&["chgrp", "0", path]));
    let after_group = owned();
    assert!(sudo(&["chown", "0", path]));
    let after_owner = owned();
    let user = std::env::var("USER").unwrap_or_default();
    sudo(&["chown", "-R", &format!("{user}:"), path]);
    assert!(
        after_group,
        "a group of root does not make the entry foreign"
    );
    assert!(
        !after_owner,
        "an entry owned by root belongs to another account"
    );
}
